    "rscript": "# Load required packages
library(haven)
library(dplyr)
library(tidyr)
library(purrr)
library(labelled)
library(readr)

# Define file paths
input_path <- "data/input/"
output_path <- "data/output/"

# Load metadata for variable mappings
metadata <- list(
  wave_four = list(
    var = "W4empsYP",
    mapping = c("-999.0" = "-2", "-94.0" = "-8", "-92.0" = "-9", "-91.0" = "-1",
