    var = "W5mainactYP",
    mapping = c("-94.0" = "-8", "1.0" = "2", "2.0" = "1", "3.0" = "1",
               "4.0" = "3", "5.0" = "2", "6.0" = "2", "7.0" = "4",
               "8.0" = "5", "9.0" = "6", "10.0" = "6", "11.0" = "6")
  ),
