    var = "W6TCurrentAct",
    mapping = c("-91.0" = "-1", "1.0" = "3", "2.0" = "3", "3.0" = "1",
               "4.0" = "2", "5.0" = "2", "6.0" = "6", "7.0" = "5",
               "8.0" = "4", "9.0" = "6", "10.0" = "1", "11.0" = "6")
