               "8.0" = "4", "9.0" = "1", "10.0" = "6", "11.0" = "6",
               "12.0" = "6", "13.0" = "6", "14.0" = "6", "15.0" = "6")
  ),
  wave_eight = list(
    var = "W8DACTIVITYC",
    mapping = c("-9.0" = "-9", "-8.0" = "-8", "-1.0" = "-1", "1.0" = "1",
               "2.0" = "1", "3.0" = "6", "4.0" = "4", "5.0" = "3",
               "6.0" = "2", "7.0" = "2", "8.0" = "6", "9.0" = "5", "10.0" = "6")
  ),
  wave_nine = list(
    var = "W9DACTIVITYC",
    mapping = c("-9.0" = "-9", "-8.0" = "-8", "-1.0" = "-1", "1.0" = "1",
